local Barber = {}
local SERVICES = {
    haircut = { name = "Striženje", cost = 10, time = 1, happiness = 2, description = "Preprosto striženje." },
    shave = { name = "Britje", cost = 5, time = 1, happiness = 1, description = "Britje brade." },
    bloodletting = { name = "Puščanje krvi", cost = 30, time = 2, health = 5, happiness = -2, description = "Terapevtsko puščanje krvi." },
    tooth_extraction = { name = "Vlečenje zoba", cost = 50, time = 1, health = 10, happiness = -5, description = "Odstranitev bolečega zoba." },
    wound_care = { name = "Nega ran", cost = 40, time = 3, health = 15, description = "Zdravljenje ran." },
    surgery = { name = "Operacija", cost = 200, time = 5, health = 30, happiness = -10, risk = 0.15, description = "Kirurški poseg." },
}
local BUILDINGS = {
    barber_shop = { name = "Brivnica", cost = { gold = 200, wood = 100 }, upkeep = 5, qualityBonus = 5 },
    surgery_room = { name = "Operacijska soba", cost = { gold = 1000, wood = 200, stone = 300 }, upkeep = 25, qualityBonus = 20 },
    apothecary_shop = { name = "Lekarnarna", cost = { gold = 800, wood = 150, stone = 200 }, upkeep = 20, qualityBonus = 15 },
    royal_barber = { name = "Kraljevski brivec", cost = { gold = 3000, wood = 300, stone = 600 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 10 },
}
Barber.buildings = {}; Barber.barber = nil; Barber.activeServices = {}; Barber.totalServices = 0; Barber.dayTimer = 0
function Barber.init() Barber.buildings={}; Barber.barber=nil; Barber.activeServices={}; Barber.totalServices=0; Barber.dayTimer=0; print("[Barber] Royal Barber & Surgeon System initialized (6 services, 4 buildings)") end
function Barber.hireBarber(n,s) s=s or math.random(35,80); local c=200+s*4; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Barber.barber={name=n or ("Brivec "..math.random(1,99)),skill=s,hiredDay=os.time(),servicesPerformed=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Brivec najet: %s (spretnost: %d)",Barber.barber.name,s),"success") end; return true end
function Barber.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Barber.build(id) local ok,e=Barber.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Barber.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Barber.getQualityBonus() local b=0; for _,bd in ipairs(Barber.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Barber.canPerform(st) local sD=SERVICES[st]; if not sD then return false,"Neznana storitev" end; if not _G.state or (_G.state.gold or 0)<sD.cost then return false,"Premalo zlata" end; if #Barber.buildings==0 then return false,"Potrebna brivnica" end; if not Barber.barber then return false,"Potreben brivec" end; return true end
function Barber.perform(st) local ok,e=Barber.canPerform(st); if not ok then return false,e end; local sD=SERVICES[st]; _G.state.gold=_G.state.gold-sD.cost; local t=sD.time; if Barber.barber then t=math.max(1,t-math.floor(Barber.barber.skill/20)) end; table.insert(Barber.activeServices,{id="srv_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),serviceType=st,serviceName=sD.name,health=sD.health or 0,happiness=sD.happiness or 0,risk=sD.risk or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Storitev: %s (%d dni)",sD.name,t),"info") end; return true end
function Barber.completeService(s) local q=1.0+(Barber.getQualityBonus()/100); if Barber.barber then q=q+(Barber.barber.skill/200) end; q=math.min(2.0,q); if s.risk>0 and math.random()<s.risk*(1-(Barber.barber and Barber.barber.skill/500 or 0)) then if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Komplikacija pri: %s!",s.serviceName),"danger") end; if _G.state and _G.state.happiness then _G.state.happiness=math.max(0,_G.state.happiness-10) end; if _G.Guard then pcall(function() _G.Guard.rulerHealth=math.max(0,_G.Guard.rulerHealth-10) end) end; return end; if _G.state and _G.state.happiness then _G.state.happiness=math.max(0,math.min(100,_G.state.happiness+s.happiness*q)) end; if s.health>0 and _G.Guard then pcall(function() _G.Guard.rulerHealth=math.min(100,_G.Guard.rulerHealth+s.health*q) end) end; Barber.totalServices=Barber.totalServices+1; if Barber.barber then Barber.barber.servicesPerformed=Barber.barber.servicesPerformed+1; if math.random()<0.15 then Barber.barber.skill=math.min(100,Barber.barber.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Storitev opravljena: %s (kakovost: %.1f)",s.serviceName,q),"success") end end
function Barber.update(dt) if not _G.state then return end; Barber.dayTimer=Barber.dayTimer+dt; if Barber.dayTimer>=30 then Barber.dayTimer=0; for i=#Barber.activeServices,1,-1 do local s=Barber.activeServices[i]; s.daysRemaining=s.daysRemaining-1; if s.daysRemaining<=0 then Barber.completeService(s); table.remove(Barber.activeServices,i) end end; local tu=0; for _,bd in ipairs(Barber.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Barber.barber then tu=tu+8 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Barber.getStats() return {numBuildings=#Barber.buildings,hasBarber=Barber.barber~=nil,barberName=Barber.barber and Barber.barber.name or "—",barberSkill=Barber.barber and Barber.barber.skill or 0,activeServices=#Barber.activeServices,totalServices=Barber.totalServices} end
return Barber
